class FakeGateway:
    def charge(self, amount):
        return "ok"

import time
class RealGateway:
    def charge(self, amount):
        time.sleep(0.5)
for g in (RealGateway(), FakeGateway()):
    t = time.perf_counter()
    Checkout(g).run(50)
    print(type(g).__name__, round(time.perf_counter() - t, 3), "s")

